document.getElementById('year').textContent=new Date().getFullYear();
const dateInput=document.querySelector('input[type="date"]');
const now=new Date();dateInput.min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
document.getElementById('enquiry-form').addEventListener('submit',function(event){event.preventDefault();const data=new FormData(this);const message=`Hello Magila / Thanushiya Bridal Studio!\nName: ${data.get('name')}\nEvent date: ${data.get('date')}\nOccasion: ${data.get('occasion')}\nLocation: ${data.get('location')}\nMy vision: ${data.get('vision')||'I would love your guidance.'}\nPlease share availability and a personalised quote.`;window.open('https://api.whatsapp.com/send?phone=917418086824&text='+encodeURIComponent(message),'_blank','noopener,noreferrer');document.getElementById('form-note').textContent='Your enquiry is ready in WhatsApp. Please press Send there to contact the studio. If it did not open, use the direct studio link.';});
